CREATE TABLE "order_pembelian" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "order_pembelian_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"nomor" varchar(30),
	"tanggal" timestamp with time zone DEFAULT now() NOT NULL,
	"id_pemasok" bigint NOT NULL,
	"id_pembuat" bigint NOT NULL,
	"status" varchar(12) DEFAULT 'DRAF' NOT NULL,
	"tanggal_dipesan" date,
	"tanggal_janji_kirim" date,
	"catatan" varchar(255),
	"alasan_tutup" varchar(255),
	"dibuat_pada" timestamp with time zone DEFAULT now() NOT NULL,
	"diubah_pada" timestamp with time zone,
	CONSTRAINT "order_pembelian_nomor_key" UNIQUE("nomor"),
	CONSTRAINT "chk_po_status" CHECK (status in ('DRAF','DIPESAN','DIKONFIRMASI','SEBAGIAN','SELESAI','DITUTUP','BATAL')),
	CONSTRAINT "chk_po_nomor" CHECK ((status = 'DRAF' and nomor is null) or status = 'BATAL'
        or (status not in ('DRAF', 'BATAL') and nomor is not null)),
	CONSTRAINT "chk_po_dipesan" CHECK (status in ('DRAF', 'BATAL') or tanggal_dipesan is not null)
);
