CREATE TABLE "order_pembelian_detail" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "order_pembelian_detail_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"id_order_pembelian" bigint NOT NULL,
	"id_barang" bigint NOT NULL,
	"qty_pesan" numeric(14, 3) NOT NULL,
	"harga_perkiraan" bigint DEFAULT 0 NOT NULL,
	"qty_konfirmasi" numeric(14, 3),
	"harga_konfirmasi" bigint,
	"qty_diterima" numeric(14, 3) DEFAULT 0 NOT NULL,
	CONSTRAINT "order_pembelian_detail_barang_key" UNIQUE("id_order_pembelian","id_barang"),
	CONSTRAINT "chk_po_detail_qty" CHECK (qty_pesan > 0 and (qty_konfirmasi is null or qty_konfirmasi >= 0) and qty_diterima >= 0),
	CONSTRAINT "chk_po_detail_harga" CHECK (harga_perkiraan >= 0 and (harga_konfirmasi is null or harga_konfirmasi >= 0))
);
