CREATE TABLE "alokasi_uang_muka" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "alokasi_uang_muka_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"id_pembayaran_pemasok" bigint NOT NULL,
	"jenis" varchar(12) NOT NULL,
	"id_penerimaan" bigint,
	"nominal" bigint NOT NULL,
	"metode_kembali" varchar(10),
	"id_shift" bigint,
	"id_pengguna" bigint NOT NULL,
	"tanggal_operasional" date NOT NULL,
	"dibuat_pada" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "chk_alokasi_jenis" CHECK (jenis in ('DIPAKAI','DIKEMBALIKAN')),
	CONSTRAINT "chk_alokasi_nominal" CHECK (nominal > 0),
	CONSTRAINT "chk_alokasi_sumber" CHECK ((jenis = 'DIPAKAI' and id_penerimaan is not null and metode_kembali is null)
        or (jenis = 'DIKEMBALIKAN' and id_penerimaan is null and metode_kembali in ('TUNAI', 'TRANSFER')))
);
